def cal_sum(n):
    if n < 0:
        return 0
    p0, p1, p2 = 3, 0, 2
    total = p0 + p1 + p2
    if n == 0:
        return p0
    if n == 1:
        return p0 + p1
    if n == 2:
        return total
    for i in range(3, n + 1):
        pn = p0 + p1
        total += pn
        # shift
        p0, p1, p2 = p1, p2, pn
    return total

