from functools import lru_cache

def get_max_sum(n: int) -> int:
    @lru_cache(maxsize=None)
    def f(x: int) -> int:
        if x < 2:  # For 0 or 1 the best is the number itself
            return x
        return max(x, f(x // 2) + f(x // 3) + f(x // 4) + f(x // 5))
    return f(n)

