import collections

def find_lists(Input):
    """
    Returns the number of list objects contained in the input tuple.

    Parameters:
    Input (tuple): A tuple that may contain nested sequences.

    Returns:
    int: The total number of list objects found within the tuple.
    """
    def count_lists(obj):
        if isinstance(obj, list):
            return 1
        if isinstance(obj, tuple):
            return sum(count_lists(item) for item in obj)
        if isinstance(obj, collections.Sequence) and not isinstance(obj, (str, bytes)):
            return sum(count_lists(item) for item in obj)
        return 0

    return count_lists(Input)

