def find_Max_Num(arr):
    """
    Given a list of digits (0-9 as integers or single-character strings), 
    returns the largest integer that can be formed by arranging them.
    If the list is empty, returns None.
    """
    if not arr:
        return None

    # Normalize to string digits
    digits = []
    for d in arr:
        if isinstance(d, int):
            if 0 <= d <= 9:
                digits.append(str(d))
            else:
                raise ValueError(f"Invalid digit integer: {d}")
        elif isinstance(d, str) and d.isdigit() and len(d) == 1:
            digits.append(d)
        else:
            raise ValueError(f"Invalid digit type: {d}")

    # Sort digits in descending order to create the largest number
    digits.sort(reverse=True)

    # Form the number string and convert to int (handles leading zeros)
    number_str = ''.join(digits)
    return int(number_str)

