def comb_sort(nums):
    """Return a new list containing the elements of `nums` sorted in ascending order using the comb sort algorithm."""
    if not isinstance(nums, list):
        raise TypeError("Input must be a list.")
    arr = list(nums)  # make a copy to avoid modifying the original list
    n = len(arr)
    gap = n
    shrink_factor = 1.3
    swapped = True
    while gap > 1 or swapped:
        # Reduce the gap according to shrink factor
        gap = int(gap / shrink_factor)
        if gap < 1:
            gap = 1
        swapped = False
        for i in range(n - gap):
            if arr[i] > arr[i + gap]:
                arr[i], arr[i + gap] = arr[i + gap], arr[i]
                swapped = True
    return arr

