import re

def parse_record(line):
    """Parse a record line into a dict.
    - Fields are separated by ";". Empty fields are ignored.
    - A field is either key=value or a bare key, which maps to True.
    - Keys and unquoted values have surrounding whitespace removed.
    - A value may be wrapped in double quotes: inside the quotes ";" is literal,
      \\" is an escaped quote, and the text is kept exactly (no trimming). The quotes themselves are removed.
    - If a key repeats, the later value wins.
    """
    def split_fields(s: str):
        fields = []
        buf = []
        in_quotes = False
        escape = False
        for ch in s:
            if escape:
                buf.append(ch)
                escape = False
                continue
            if ch == '\\':
                if in_quotes:
                    escape = True
                else:
                    buf.append(ch)
                continue
            if ch == '"' :
                in_quotes = not in_quotes
                continue
            if ch == ';' and not in_quotes:
                fields.append(''.join(buf))
                buf = []
                continue
            buf.append(ch)
        if buf:
            fields.append(''.join(buf))
        return fields

    result = {}
    for field in split_fields(line):
        if not field.strip():
            continue
        if '=' in field:
            key, value = field.split('=', 1)
            key = key.strip()
            value = value.strip()
            if value.startswith('"') and value.endswith('"'):
                # remove the surrounding quotes and unescape \"
                inside = value[1:-1]
                inside = inside.replace('\\"', '"')
                result[key] = inside
            else:
                result[key] = value
        else:
            key = field.strip()
            result[key] = True
    return result

# Basic tests
if __name__ == "__main__":
    assert parse_record('name=Ana; city = Lyon') == {"name": "Ana", "city": "Lyon"}
    assert parse_record('note="a;b"; urgent') == {"note": "a;b", "urgent": True}
    assert parse_record('k1=v1;k2="v2;with;semicolons";k1=override') == {
        "k1": "override", "k2": "v2;with;semicolons"
    }
    print("All tests passed.")

