def find_lists(Input):
    """
    Return the number of list objects present in the given tuple.
    Counts all lists, including those nested inside other lists or tuples.
    """
    if not isinstance(Input, tuple):
        raise ValueError("Input must be a tuple")
    count = 0
    for element in Input:
        if isinstance(element, list):
            count += 1
            # Count lists nested inside this list
            count += sum(1 for sub in element if isinstance(sub, list))
        elif isinstance(element, tuple):
            count += find_lists(element)  # recursive for nested tuples
    return count

