def cal_sum(n):
    """Return the sum of the Perrin sequence from P0 to Pn inclusive."""
    if n < 0:
        raise ValueError("n must be non‑negative")
    # Base cases
    if n == 0:
        return 3
    if n == 1:
        return 3 + 0
    if n == 2:
        return 3 + 0 + 2

    # Initialize first three terms
    a, b, c = 3, 0, 2  # P0, P1, P2
    total = a + b + c

    # Compute subsequent terms iteratively
    for i in range(3, n + 1):
        d = a + b          # P_{i} = P_{i-2} + P_{i-3}
        total += d
        # shift window for next iteration
        a, b, c = b, c, d
    return total

# Example usage
if __name__ == "__main__":
    import sys
    for n in range(10):
        print(f"Sum up to P{n} =", cal_sum(n))

