sys.setrecursionlimit(10**6)

def get_max_sum(n: int) -> int:
    if n < 0:
        raise ValueError("n must be non-negative")
    memo = {0: 0}

    def f(x: int) -> int:
        if x in memo:
            return memo[x]
        # recursive computation
        val = max(x, f(x // 2) + f(x // 3) + f(x // 4) + f(x // 5))
        memo[x] = val
        return val

    return f(n)

