def check_Consecutive(l):
    """
    Returns True if the list `l` contains consecutive numbers in any order,
    otherwise returns False. An empty list or a list with a single element
    is considered not to contain a sequence of consecutive numbers.
    """
    if not l or len(l) < 2:
        return False
    sorted_l = sorted(l)
    for i in range(1, len(sorted_l)):
        if sorted_l[i] - sorted_l[i - 1] != 1:
            return False
    return True

