def dict_depth(d):
    """Return the maximum depth of nested dictionaries within `d`."""
    if not isinstance(d, dict):
        return 0
    if not d:
        return 1
    max_subdepth = 0
    for v in d.values():
        if isinstance(v, dict):
            sub_depth = dict_depth(v)
            if sub_depth > max_subdepth:
                max_subdepth = sub_depth
    return 1 + max_subdepth

