def is_sublist(l, s):
    """Return True if list s occurs as a contiguous sublist of list l."""
    len_l, len_s = len(l), len(s)
    if len_s == 0:
        return True
    if len_s > len_l:
        return False
    for i in range(len_l - len_s + 1):
        if l[i:i+len_s] == s:
            return True
    return False

