def set_left_most_unset_bit(n):
    """
    Set the left-most unset bit (the most significant 0 bit) in the binary
    representation of n. For n >= 0. If all bits up to the current most
    significant 1 are set, the next higher bit is set.

    Example:
        n = 0b1011  (11)
        left-most unset bit is at position 3 (value 8)
        result = 0b1111 (15)
    """
    if n < 0:
        raise ValueError("n must be non-negative")

    # Determine the bit length (msb position + 1)
    bit_len = n.bit_length()

    # Check bits from most significant downto 0
    for pos in range(bit_len - 1, -1, -1):
        if not (n >> pos) & 1:
            return n | (1 << pos)

    # All bits up to bit_len-1 are 1 → set the next bit
    return n | (1 << bit_len)

# Example usage:
if __name__ == "__main__":
    tests = [0, 1, 2, 3, 6, 7, 15, 16]
    for t in tests:
        print(f"{t:#b} -> {set_left_most_unset_bit(t):#b}")

