def check_Consecutive(l):
    """
    Return True if the list l consists of consecutive integers
    (in any order).  Empty list and single-element list are considered
    consecutive.
    """
    if len(l) <= 1:
        return True
    s = sorted(l)
    for i in range(1, len(s)):
        if s[i] - s[i - 1] != 1:
            return False
    return True

