import collections

def dict_depth(d):
    """
    Return the maximum depth of nested dictionaries in `d`.
    The depth of a non-nested dictionary is 1.
    If the dictionary is empty, its depth is 1.
    """
    if not isinstance(d, dict) or not d:
        # Either not a dict or empty dict
        return 0 if d is None else 1

    max_child_depth = 0
    for v in d.values():
        if isinstance(v, dict):
            child_depth = dict_depth(v)
            if child_depth > max_child_depth:
                max_child_depth = child_depth
    return 1 + max_child_depth

# Example usage
if __name__ == "__main__":
    nested = {"a": 1, "b": {"c": 2, "d": {"e": 3}}}
    print(dict_depth(nested))  # Output: 3
    print(dict_depth({"x": {}}))  # Output: 2
    print(dict_depth({}))  # Output: 0

