from functools import lru_cache

def sequence(n: int) -> int:
    """
    Return the n-th term (0-indexed) of the Newman–Conway sequence
    defined by:
        a(0) = 1
        a(1) = 1
        a(n) = a(a(n-1)) + a(n - a(n-1)) for n >= 2
    """
    @lru_cache(maxsize=None)
    def a(k: int) -> int:
        if k == 0 or k == 1:
            return 1
        return a(a(k - 1)) + a(k - a(k - 1))

    if n < 0:
        raise ValueError("n must be non-negative")
    return a(n)

